<?php require "includes.php";$q=$_GET["q"]??"";$st=$pdo->prepare("SELECT * FROM kegiatan WHERE nama LIKE ? OR deskripsi LIKE ? ORDER BY tanggal DESC");$st->execute(["%$q%","%$q%"]);$rows=$st->fetchAll();?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kegiatan | HMPSIF</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/style_modern.css" rel="stylesheet"></head><body><?php include "navbar.php";?><main class="section"><div class="container"><div class="eyebrow">Aktivitas</div><h1 class="section-title">Kegiatan HMTI</h1><form class="my-4"><input name="q" value="<?=e($q)?>" class="form-control form-control-lg" placeholder="Cari kegiatan..."></form><div class="row g-4"><?php foreach($rows as $r):?><div class="col-md-6 col-lg-4"><div class="card card-modern overflow-hidden filter-item"><img src="<?=e($r["poster"])?>" class="program-img"><div class="card-body p-4"><small class="text-primary"><?=date("d M Y",strtotime($r["tanggal"]))?> • <?=e($r["lokasi"])?></small><h5 class="mt-2"><?=e($r["nama"])?></h5><p class="text-muted"><?=e($r["deskripsi"])?></p><span class="badge badge-soft"><?=e($r["status"])?></span></div></div></div><?php endforeach;?></div></div></main><?php include "footer.php";?></body></html>